	/* initializeTile */
		function initializeTile(tile) {
			tile.initialized = true
			tile.element.setAttribute("initialized", tile.initialized)
		}

	/* swapTile */
		function swapTile(event) {
			// element
				const element = event.target.closest(".postcard-tile")
				if (!element) {
					return
				}

			// tile
				const x = Number(element.getAttribute("x"))
				const y = Number(element.getAttribute("y"))
				const tile = STATE.tiles[`${x}_${y}`]
				if (!tile) {
					return
				}

			// direction
				const direction = event.target.closest(".postcard-tile-overlay-swap-button").getAttribute("direction")
				if (!direction) {
					return
				}

			// get other tile
				const otherX = (direction == "left" ? x - 1 : direction == "right" ? x + 1 : x)
				const otherY = (direction == "up"   ? y - 1 : direction == "down"  ? y + 1 : y)
				const otherTile = STATE.tiles[`${otherX}_${otherY}`]
				if (!otherTile) {
					return
				}

			// swap values
				const tempTile = {
					initialized: tile.initialized,
					prompt: tile.prompt,
					dx: tile.dx,
					dy: tile.dy,
					scalePower: tile.scalePower,
					rotation: tile.rotation,
					image: tile.image,
				}

				tile.initialized = otherTile.initialized
				tile.prompt = otherTile.prompt
				tile.dx = otherTile.dx
				tile.dy = otherTile.dy
				tile.scalePower = otherTile.scalePower
				tile.rotation = otherTile.rotation
				tile.image = otherTile.image

				otherTile.initialized = tempTile.initialized
				otherTile.prompt = tempTile.prompt
				otherTile.dx = tempTile.dx
				otherTile.dy = tempTile.dy
				otherTile.scalePower = tempTile.scalePower
				otherTile.rotation = tempTile.rotation
				otherTile.image = tempTile.image

			// update inputs
				setInputs(tile)
				setInputs(otherTile)

			// overlay
				closeOverlay(null, tile)
				openOverlay(null, otherTile)

			// draw
				drawTileImage(tile)
				drawTileImage(otherTile)
		}

/*** overlay ***/
	/* openOverlay */
		function openOverlay(event, tile) {
			if (tile) {
				tile.element.setAttribute("overlay", true)
				return
			}

			if (event.target.className !== "postcard-tile-overlay") {
				return
			}
			event.target.closest(".postcard-tile").setAttribute("overlay", true)
		}

	/* closeOverlay */
		function closeOverlay(event, tile) {
			if (tile) {
				tile.element.removeAttribute("overlay")
				return
			}

			event.target.closest(".postcard-tile").removeAttribute("overlay")
		}

/*** settings ***/
	/* setTileScale */
		function setTileScale(event) {
			// element
				const element = event.target.closest(".postcard-tile")
				if (!element) {
					return
				}

			// tile
				const x = Number(element.getAttribute("x"))
				const y = Number(element.getAttribute("y"))
				const tile = STATE.tiles[`${x}_${y}`]
				if (!tile) {
					return
				}

			// value
				tile.scalePower = Number(event.target.value)

			// update
				drawTileImage(tile)
		}

